import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Plus, Receipt } from "lucide-react";
import { api } from "../api";
import { formatMoney, formatDate } from "../utils";

function ExpenseTracker() {
  const [expenses, setExpenses] = useState(null);
  const [error, setError] = useState("");

  useEffect(() => {
    api.get("/expenses").then(setExpenses).catch((err) => setError(err.message));
  }, []);

  return (
    <div className="px-8 lg:px-14 py-10 max-w-4xl">
      <div className="flex items-end justify-between gap-6">
        <div>
          <p className="font-mono text-xs tracking-widest uppercase text-brand">All groups</p>
          <h1 className="mt-3 text-6xl font-bold tracking-tight">Expenses</h1>
        </div>
        <Link to="/expenses/new" className="flex items-center gap-2 px-7 py-4 rounded-2xl bg-ink text-white font-semibold hover:bg-inkSoft transition-colors">
          <Plus size={20} /> Add expense
        </Link>
      </div>

      <div className="mt-10 rounded-3xl bg-white border border-slate-200 px-8">
        {error && <p className="py-6 text-rose">{error}</p>}
        {!expenses && !error && <p className="py-6 text-slate-500">Loading...</p>}
        {expenses && expenses.length === 0 && <p className="py-6 text-slate-500">No expenses yet.</p>}
        {expenses && expenses.length > 0 && (
          <ul className="divide-y divide-slate-200">
            {expenses.map((e) => (
              <li key={e.id} className="flex items-center gap-5 py-6">
                <div className="w-14 h-14 rounded-2xl bg-mint text-money flex items-center justify-center">
                  <Receipt size={22} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-semibold text-lg">{e.title}</p>
                  <p className="text-slate-500">{e.paidByMe ? "You paid" : `${e.paidByName} paid`}</p>
                  <p className="text-sm text-slate-400">{e.groupName}</p>
                </div>
                <div className="text-right">
                  <p className="font-mono font-bold text-lg">{formatMoney(e.amount)}</p>
                  <p className="text-sm text-slate-400">{formatDate(e.createdAt)}</p>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default ExpenseTracker;
